<script setup>
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { api, errorMessage, localTime } from './api'
import DeleteCapture from './DeleteCapture.vue'
import ScreenshotMetadata from './ScreenshotMetadata.vue'
const props=defineProps({timezone:{type:String,default:'UTC'}})
const kind=ref('screenshots'),rows=ref([]),page=ref(1),last=ref(1),total=ref(0),busy=ref(false),error=ref(''),selected=ref(null),failed=reactive({}),imageFailed=ref(false)
const message=ref('');async function deleted(text){message.value=text;await load()}
const filters=reactive({from:'',to:''});let generation=0
async function load(reset=false){if(reset)page.value=1;const current=++generation;busy.value=true;error.value='';selected.value=null;try{const {data}=await api.get('/local/my-data',{params:{kind:kind.value,page:page.value,timezone:props.timezone,...(filters.from?{from:filters.from}:{}),...(filters.to?{to:filters.to}:{})}});if(current!==generation)return;rows.value=data.data;last.value=data.last_page;total.value=data.total;Object.keys(failed).forEach(k=>delete failed[k])}catch(err){if(current===generation){error.value=errorMessage(err);rows.value=[]}}finally{if(current===generation)busy.value=false}}
function switchKind(value){kind.value=value;rows.value=[];load(true)}
function imageURL(id,thumb=false){return '/local/my-screenshot?id='+encodeURIComponent(id)+(thumb?'&thumbnail=1':'')}
function open(item){selected.value=item;imageFailed.value=false}
function escape(event){if(event.key==='Escape')selected.value=null}
onMounted(()=>{load();window.addEventListener('keydown',escape)});onUnmounted(()=>{generation++;window.removeEventListener('keydown',escape)})
</script>
<template><section><div class="card"><div class="card-heading"><div><h2>What your organization received</h2><p class="small muted">Your records across your devices. Queued uploads appear after the server receives them. Retention rules may remove older records.</p></div></div><div class="personnel-tabs"><button :class="{primary:kind==='screenshots'}" @click="switchKind('screenshots')">Screenshots</button><button :class="{primary:kind==='activity'}" @click="switchKind('activity')">Application activity & URLs</button></div><form class="form-grid" @submit.prevent="load(true)"><label>From date<input v-model="filters.from" type="date"></label><label>To date<input v-model="filters.to" type="date" :min="filters.from || undefined"></label><div class="inline-actions"><button class="primary" :disabled="busy">Apply dates</button><button type="button" :disabled="busy" @click="filters.from='';filters.to='';load(true)">Clear</button></div></form><p class="employee-caption">Date filters use {{timezone}}. Displayed timestamps use your browser's local timezone. This is your server history, not just the latest local preview.</p></div><p v-if="message" class="notice" role="status">{{message}}</p><p v-if="error" class="notice danger" role="alert">{{error}}</p><p v-if="busy" class="muted" role="status">Loading server records…</p><div v-if="kind==='screenshots'" class="gallery employee-server-gallery"><article v-for="item in rows" :key="item.id" class="capture-card"><button class="full" @click="open(item)"><div class="capture-preview"><img v-if="!failed[item.id]" :src="imageURL(item.id,true)" loading="lazy" :alt="'Your screenshot from '+localTime(item.captured_at)" @error="failed[item.id]=true"><p v-else class="employee-empty">Preview unavailable. Select to retry the full image.</p></div><div class="capture-info"><strong>{{localTime(item.captured_at)}}</strong><small>{{item.device_name}} · {{item.app_name || 'Desktop'}}</small><p>Received {{localTime(item.received_at)}}</p><p v-if="item.deleted" class="pill neutral">Deleted {{localTime(item.deleted_at)}}{{item.deletion_cleanup_pending?" · Cleanup pending":""}}</p></div></button><DeleteCapture :item="item" @deleted="deleted" /></article></div><section v-else class="card table-card"><div class="table-scroll"><table><thead><tr><th>Captured / received</th><th>Device</th><th>Application</th><th>Window title</th><th>Collected URL</th><th>Estimated seconds / observed switch</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{localTime(item.captured_at)}}<small>Received {{localTime(item.received_at)}}</small></td><td>{{item.device_name}}</td><td>{{item.app_name}}</td><td class="wrap">{{item.window_title || '—'}}</td><td class="wrap">{{item.url || 'Not collected / unavailable'}}</td><td>{{item.duration_seconds ?? 'Unknown'}} / {{item.app_switches ?? 'Unknown'}}</td></tr></tbody></table></div></section><p v-if="!busy && !error && !rows.length" class="card employee-empty">No retained records match these dates.</p><div class="pagination"><span>{{total}} records · Page {{page}} of {{last}}</span><div><button :disabled="busy || page<=1" @click="page--;load()">Previous</button><button :disabled="busy || page>=last" @click="page++;load()">Next</button></div></div><div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="image-modal" role="dialog" aria-modal="true" aria-label="Your uploaded screenshot"><div class="image-toolbar"><div><strong>{{localTime(selected.captured_at)}} · {{selected.device_name}}</strong><small>Received {{localTime(selected.received_at)}}</small></div><button @click="selected=null">Close</button></div><img v-if="!imageFailed" :src="imageURL(selected.id)" alt="Full screenshot stored on the server" @error="imageFailed=true"><p v-else role="alert">This screenshot could not be loaded. It may have expired under your organization's retention policy, or storage may be unavailable.</p><ScreenshotMetadata :item="selected" /><p class="employee-reason">{{selected.window_title}}<br>{{selected.url || ''}}</p></section></div></section></template>

